def style_templates() -> tuple[dict[str, Any], ...]:
    """Return fresh copies of the eight upstream Creator presets."""
    out: list[dict[str, Any]] = [deepcopy(_BASE)]
    for diff in _DIFFS:
        item = deepcopy(_BASE)
        item.update(deepcopy(diff))
        out.append(item)
    return tuple(out)


def resolve_style_template(value: str | int) -> tuple[int, str, dict[str, Any]]:
    """Resolve a preset by 1-based index or case-insensitive name."""
    if isinstance(value, int) or (isinstance(value, str) and value.strip().isdigit()):
        index = int(value) - 1
        if index < 0 or index >= len(STYLE_TEMPLATE_NAMES):
            raise ValueError(f"style template index must be 1-{len(STYLE_TEMPLATE_NAMES)}")
    else:
        needle = str(value).strip().casefold()
        matches = [i for i, name in enumerate(STYLE_TEMPLATE_NAMES) if name.casefold() == needle]
        if not matches:
            choices = ", ".join(STYLE_TEMPLATE_NAMES)
            raise ValueError(f"unknown style template {value!r}; choose one of: {choices}")
        index = matches[0]
    templates = style_templates()
    return index, STYLE_TEMPLATE_NAMES[index], templates[index]


def apply_style_template(project: dict[str, Any], value: str | int) -> tuple[int, str]:
    """Apply a preset exactly like Object.assign(app.styling, preset)."""
    index, name, preset = resolve_style_template(value)
    styling = project.setdefault("styling", {})
    if not isinstance(styling, dict):
        raise ValueError("project.styling must be an object")
    styling.update(preset)
    return index, name
